import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./BookingHistoryPage.css";

function BookingHistoryPage() {
  const navigate = useNavigate();
  const [bookingHistory, setBookingHistory] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadBookings();
  }, []);

  const loadBookings = () => {
    const userId = localStorage.getItem("userId");
    const allBookings = JSON.parse(localStorage.getItem("bookings")) || [];
    const userBookings = allBookings.filter(
      (b) => String(b.userId) === String(userId)
    );
    setBookingHistory(userBookings);
    setLoading(false);
  };

  const cancelBooking = (index) => {
    if (window.confirm("Are you sure you want to cancel this booking?")) {
      const userId = localStorage.getItem("userId");
      let allBookings = JSON.parse(localStorage.getItem("bookings")) || [];

      // Find the booking in the global list, not just filtered
      const bookingToCancel = bookingHistory[index];
      allBookings = allBookings.filter(
        (b) =>
          !(
            String(b.userId) === String(userId) &&
            b.slotNumber === bookingToCancel.slotNumber &&
            b.date === bookingToCancel.date &&
            b.time === bookingToCancel.time &&
            b.vehicleNo === bookingToCancel.vehicleNo
          )
      );

      // Save updated list to localStorage
      localStorage.setItem("bookings", JSON.stringify(allBookings));

      // Refresh UI
      loadBookings();
      alert("Booking canceled successfully.");
    }
  };

  return (
    <div className="history-container">
      <h1>My Booking History</h1>
      <button className="back-btn" onClick={() => navigate("/home")}>
        Back to Home
      </button>

      {loading ? (
        <p>Loading booking history...</p>
      ) : bookingHistory.length === 0 ? (
        <p>No booking history found.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Slot</th>
              <th>Vehicle Type</th>
              <th>Vehicle No</th>
              <th>Date</th>
              <th>Time</th>
              <th>Duration</th>
              <th>Contact</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {bookingHistory.map((booking, index) => (
              <tr key={index}>
                <td>{booking.slotNumber}</td>
                <td>{booking.vehicleType}</td>
                <td>{booking.vehicleNo}</td>
                <td>{booking.date}</td>
                <td>{booking.time}</td>
                <td>{booking.duration}</td>
                <td>{booking.contact || "-"}</td>
                <td>
                  <button
                    className="cancel-btn"
                    onClick={() => cancelBooking(index)}
                  >
                    Cancel
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default BookingHistoryPage;
